package com.fixmer.mared.technology.server.setup;
import com.fixmer.mared.gui2.framework.screen.MaredScreen;import com.google.gson.*;import net.minecraft.client.gui.GuiGraphics;import net.minecraft.client.gui.components.*;import net.minecraft.client.gui.screens.*;import net.minecraft.network.chat.Component;import java.nio.file.*;import java.util.*;
/** Two compact native pages: certificate settings and observed owner publication state. */
public final class HttpsScreen78 extends MaredScreen {
 private final Screen previous;private final HttpsService78 service=new HttpsService78();private JsonObject prefs;private EditBox root,publicFolder,cert,key,bind;private final List<Button> buttons=new ArrayList<>();private int left,w,page,top,scroll,maxScroll;private long due;private String rootValue;private boolean loaded;private String hydratedRoot="";
 public HttpsScreen78(Screen previous,String root){super(tr("title"));this.previous=previous;rootValue=root;prefs=DedicatedPanelService75.preferences();}
 private static Component tr(String k,Object...args){return Component.translatable("mared.https78."+k,args);}
 private String pref(String k,String fallback){try{return prefs.get("https78"+k).getAsString();}catch(Exception bad){return fallback;}}
 private Button button(Component title,int x,int y,int width,Runnable action){Button b=addRenderableWidget(Button.builder(title,a->action.run()).bounds(x,y,width,20).build());buttons.add(b);return b;}
 private EditBox field(String label,int y,String value,boolean directory,boolean picker){EditBox box=addRenderableWidget(new EditBox(font,left+82,y,w-82-(picker?34:0),20,tr(label)));box.setMaxLength(4096);box.setValue(value);if(picker)button(Component.literal("…"),left+w-30,y,30,()->browse(box,directory));return box;}
 @Override protected void init(){collect();buttons.clear();w=Math.max(250,Math.min(680,width-24));left=(width-w)/2;button(tr(page==0?"status_page":"settings_page"),left,32,w,()->{collect();page=1-page;scroll=0;rebuildWidgets();});root=field("root",56,rootValue,true,true);int bw=(w-8)/3;
  if(page==1){publicFolder=field("public",80,pref("Public",""),true,true);cert=field("cert",104,pref("Cert",""),false,true);key=field("key",128,pref("Key",""),false,true);bind=field("bind",152,pref("Bind","127.0.0.1"),false,false);button(tr("check"),left,176,(w-4)/2,()->operation("check"));button(tr("save"),left+(w+4)/2,176,(w-4)/2,()->confirm("save_confirm",()->operation("save")));top=201;}
  else{publicFolder=cert=key=bind=null;button(tr("refresh"),left,80,bw,()->operation("status"));button(tr("probe"),left+bw+4,80,bw,()->operation("probe"));button(tr("disable"),left+2*(bw+4),80,bw,()->confirm("disable_confirm",()->operation("disable")));top=106;}
  button(tr("back"),left,height-26,w,this::onClose);if(!loaded&&!rootValue.isBlank()){loaded=true;operation("status");}tick();
 }
 private void collect(){if(prefs==null)return;if(root!=null)rootValue=root.getValue().trim();if(publicFolder!=null){prefs.addProperty("https78Public",publicFolder.getValue().trim());prefs.addProperty("https78Cert",cert.getValue().trim());prefs.addProperty("https78Key",key.getValue().trim());prefs.addProperty("https78Bind",bind.getValue().trim());}DedicatedPanelService75.save(prefs);}
 private void browse(EditBox box,boolean directory){collect();Path path;try{path=box.getValue().isBlank()?minecraft.gameDirectory.toPath():Path.of(box.getValue());}catch(Exception bad){path=minecraft.gameDirectory.toPath();}minecraft.setScreen(new LocalPickerScreen68(this,directory,path,p->{box.setValue(p.toString());collect();},!directory));}
 private void confirm(String message,Runnable action){collect();minecraft.setScreen(new ConfirmScreen(yes->{minecraft.setScreen(this);if(yes)action.run();},tr("confirm_title"),tr(message)));}
 private void operation(String op){collect();service.run(op,rootValue,pref("Public",""),pref("Cert",""),pref("Key",""),pref("Bind","127.0.0.1"));due=System.nanoTime()+5_000_000_000L;}
 @Override public void tick(){if(root==null)return;for(Button b:buttons)b.active=!service.busy();root.setEditable(!service.busy());for(EditBox box:new EditBox[]{publicFolder,cert,key,bind})if(box!=null)box.setEditable(!service.busy());if(page==0&&!service.busy()&&System.nanoTime()>due&&!root.getValue().isBlank())operation("status");JsonObject data=service.data();if(!loaded||!root.getValue().trim().equals(service.root()))return;try{JsonObject cfg=data.getAsJsonObject("configuration");if(!service.busy()&&!hydratedRoot.equals(service.root())&&cfg.has("public")){prefs.addProperty("https78Public",cfg.get("public").getAsString());prefs.addProperty("https78Cert",cfg.get("cert").getAsString());prefs.addProperty("https78Key",cfg.get("key").getAsString());prefs.addProperty("https78Bind",cfg.get("bind").getAsString());DedicatedPanelService75.save(prefs);hydratedRoot=service.root();if(publicFolder!=null){publicFolder.setValue(pref("Public",""));cert.setValue(pref("Cert",""));key.setValue(pref("Key",""));bind.setValue(pref("Bind","127.0.0.1"));}}}catch(Exception ignored){}}
 @Override public void removed(){collect();}@Override public void onClose(){if(!service.busy()){collect();minecraft.setScreen(previous);}}@Override public boolean isPauseScreen(){return false;}
 @Override public boolean mouseScrolled(double x,double y,double dx,double dy){scroll=Math.max(0,Math.min(maxScroll,scroll+(int)(-dy*24)));return true;}
 private List<Component> lines(){List<Component> out=new ArrayList<>();String result=service.result();out.add(tr("result."+(Set.of("IDLE","WORKING","STATUS","PROBE_OK","CHECKED","SAVED").contains(result)?result:"ERROR")));if(result.startsWith("HTTPS78_")){out.add(tr("error."+Errors78.key(result)));out.add(Component.literal(result));}out.add(tr("lifetime_hint"));if(!root.getValue().trim().equals(service.root())){out.add(tr("refresh_hint"));return out;}JsonObject d=service.data();for(String name:List.of("state","clientTrust"))if(d.has(name))out.add(tr(name+"."+d.get(name).getAsString()));if(d.has("code")&&!d.get("code").getAsString().isEmpty()){String code=d.get("code").getAsString();out.add(tr("error."+Errors78.key(code)));out.add(Component.literal(code));}try{JsonObject cfg=d.has("inspection")?d.getAsJsonObject("inspection"):d.getAsJsonObject("configuration");for(String k:List.of("endpoint","bind","fingerprint"))if(cfg.has(k))out.add(tr(k+"_value",cfg.get(k).getAsString()));if(cfg.has("expires"))out.add(tr("expires_value",java.time.Instant.ofEpochMilli(Long.parseLong(cfg.get("expires").getAsString())).toString()));}catch(Exception ignored){}return out;}
 @Override public void render(GuiGraphics g,int mx,int my,float dt){g.fill(0,0,width,height,0xF0151820);g.drawCenteredString(font,title,width/2,10,0xFFFFFFFF);int y=62;for(String k:page==1?List.of("root","public","cert","key","bind"):List.of("root")){g.drawString(font,tr(k),left,y,0xFFCCD0DC,false);y+=24;}List<net.minecraft.util.FormattedCharSequence> rows=new ArrayList<>();for(Component c:lines())rows.addAll(font.split(c,w-8));int bottom=Math.max(top,height-32),step=font.lineHeight+3;maxScroll=Math.max(0,rows.size()*step-(bottom-top));scroll=Math.min(scroll,maxScroll);if(bottom>top){g.enableScissor(left,top,left+w,bottom);int at=top-scroll;for(var line:rows){if(at+step>=top&&at<bottom)g.drawString(font,line,left,at,0xFFCCD0DC,false);at+=step;}g.disableScissor();}super.render(g,mx,my,dt);}
 private static final class Errors78 {static String key(String code){return switch(code){case "HTTPS78_HOSTNAME"->"hostname";case "HTTPS78_CERTIFICATE_DATE"->"date";case "HTTPS78_KEY_PAIR"->"key";case "HTTPS78_OFFLINE_LOOPBACK"->"offline";case "HTTPS78_LISTEN_FAILED"->"listen";case "HTTPS78_TLS_TRUST"->"trust";case "HTTPS78_UPDATE_BUSY"->"busy";case "HTTPS78_CERTIFICATE_CHANGED","HTTPS78_CONFIG_CHANGED"->"changed";case "HTTPS78_OFFER_TIME"->"offer_time";case "HTTPS78_PUBLIC_REJECTED"->"public";case "HTTPS78_TIMEOUT"->"timeout";case "HTTPS78_NOT_CONFIGURED"->"not_configured";case "HTTPS78_VERSION_OR_GAME"->"version";case "HTTPS78_PRIVATE_KEY_LOCATION"->"private_location";case "HTTPS78_CERTIFICATE_FILES"->"files";case "HTTPS78_NEW_OWNER_REQUIRED"->"owner";case "HTTPS78_ENDPOINT_IDENTITY"->"identity";default->"generic";};}}
}
